#!/usr/bin/env python3
# -*- coding: utf-8 -*-
"""
tables_check.py - Says whether a rebuilt set of ladder tables is the published one.

    python src/build_ladder_tables.py --output_dir results/smoke_test/tables
    python tests/tables_check.py results/tables results/smoke_test/tables

What is compared, and how:

  table*.csv            cell by cell: the same text, or two numbers equal to 1e-9
  ladder_tables.tex     the same text
  ladder_tables.md      the same text, except the date and the commit of its
                        "Generated by" line
  ladder_summary.json   the same values (numbers to 1e-9), except generated_utc,
                        git_commit and environment

The three fields left out say when, from which commit and with which library
versions the tables were built; they change with every run and say nothing
about the results. Line endings are ignored. Numbers are allowed to differ
after the ninth significant digit because the CSV files hold unrounded values
and another version of numpy or scipy may round the last digit otherwise; the
script says when that tolerance was needed.

Exit code 0 when the two sets are the same, 1 when they differ, 2 when a folder
is missing. Standard library only. It is used by tests/test_published_tables.py
and by the continuous-integration workflow.
"""
import csv
import json
import math
import os
import re
import sys

TABLES = ["table1_ladder.csv", "table2_decomposition.csv", "table3_latency.csv", "table4_repeatability.csv",
          "table5_per_class.csv", "table6_gap_contrasts.csv", "table7_attribution.csv",
          "table8_representativeness.csv"]
TEXT_FILES = ["ladder_tables.tex", "ladder_tables.md"]
SUMMARY = "ladder_summary.json"
SUMMARY_IGNORED = ("generated_utc", "git_commit", "environment")
REL_TOL = 1e-9
# "... on 2026-11-14T19:24:48+00:00 (commit 244308db71)." in the first paragraph of the Markdown file
STAMP = re.compile(r" on \S+ \(commit [0-9a-f]+\)")


def _number(text):
    try:
        value = float(text)
    except (TypeError, ValueError):
        return None
    return value if math.isfinite(value) else None


def _same_number(a, b):
    return math.isclose(a, b, rel_tol=REL_TOL, abs_tol=1e-12)


def compare_csv(name, published, rebuilt, out):
    """Appends the differences of one table to out; returns how many cells needed the tolerance."""
    with open(published, encoding="utf-8", newline="") as fh:
        rows_a = list(csv.reader(fh))
    with open(rebuilt, encoding="utf-8", newline="") as fh:
        rows_b = list(csv.reader(fh))
    if len(rows_a) != len(rows_b):
        out.append("%s: %d rows published, %d rebuilt" % (name, len(rows_a), len(rows_b)))
        return 0
    rounded = 0
    for r, (row_a, row_b) in enumerate(zip(rows_a, rows_b)):
        if len(row_a) != len(row_b):
            out.append("%s row %d: %d cells published, %d rebuilt" % (name, r + 1, len(row_a), len(row_b)))
            continue
        for c, (a, b) in enumerate(zip(row_a, row_b)):
            if a == b:
                continue
            x, y = _number(a), _number(b)
            if x is not None and y is not None and _same_number(x, y):
                rounded += 1
                continue
            column = rows_a[0][c] if c < len(rows_a[0]) else str(c)
            out.append("%s row %d, %s: published %s, rebuilt %s" % (name, r + 1, column, a, b))
    return rounded


def compare_text(name, published, rebuilt, out):
    with open(published, encoding="utf-8") as fh:
        a = fh.read().split("\n")
    with open(rebuilt, encoding="utf-8") as fh:
        b = fh.read().split("\n")
    if name.endswith(".md"):
        a = [STAMP.sub(" on <date> (commit <commit>)", line) for line in a]
        b = [STAMP.sub(" on <date> (commit <commit>)", line) for line in b]
    if len(a) != len(b):
        out.append("%s: %d lines published, %d rebuilt" % (name, len(a), len(b)))
        return
    for i, (x, y) in enumerate(zip(a, b)):
        if x != y:
            out.append("%s line %d differs:\n    published: %s\n    rebuilt:   %s" % (name, i + 1, x[:200], y[:200]))


def _compare_values(path, a, b, out, counter):
    if isinstance(a, dict) and isinstance(b, dict):
        for key in sorted(set(a) | set(b)):
            if key not in a or key not in b:
                out.append("%s: %s only in the %s file" % (SUMMARY, path + key, "published" if key in a else "rebuilt"))
            else:
                _compare_values(path + key + ".", a[key], b[key], out, counter)
    elif isinstance(a, list) and isinstance(b, list):
        if len(a) != len(b):
            out.append("%s: %s has %d items published, %d rebuilt" % (SUMMARY, path.rstrip("."), len(a), len(b)))
            return
        for i, (x, y) in enumerate(zip(a, b)):
            _compare_values("%s%d." % (path, i), x, y, out, counter)
    elif a != b:
        numbers = all(isinstance(v, (int, float)) and not isinstance(v, bool) for v in (a, b))
        if numbers and _same_number(float(a), float(b)):
            counter[0] += 1
        else:
            out.append("%s: %s published %r, rebuilt %r" % (SUMMARY, path.rstrip("."), a, b))


def compare_summary(published, rebuilt, out):
    with open(published, encoding="utf-8") as fh:
        a = json.load(fh)
    with open(rebuilt, encoding="utf-8") as fh:
        b = json.load(fh)
    for key in SUMMARY_IGNORED:
        a.pop(key, None)
        b.pop(key, None)
    counter = [0]
    _compare_values("", a, b, out, counter)
    return counter[0]


def differences(published_dir, rebuilt_dir):
    """(differences, values that needed the tolerance) between two folders of tables."""
    out, rounded = [], 0
    for name in TABLES + TEXT_FILES + [SUMMARY]:
        published, rebuilt = os.path.join(published_dir, name), os.path.join(rebuilt_dir, name)
        missing = [which for which, path in (("published", published), ("rebuilt", rebuilt)) if not os.path.isfile(path)]
        if missing:
            out.append("%s: missing in the %s folder" % (name, " and the ".join(missing)))
        elif name.endswith(".csv"):
            rounded += compare_csv(name, published, rebuilt, out)
        elif name == SUMMARY:
            rounded += compare_summary(published, rebuilt, out)
        else:
            compare_text(name, published, rebuilt, out)
    return out, rounded


def main(argv):
    if len(argv) != 3:
        print("usage: python tests/tables_check.py <published tables folder> <rebuilt tables folder>")
        return 2
    for folder in argv[1:]:
        if not os.path.isdir(folder):
            print("ERROR: %s is not a folder" % folder)
            return 2
    found, rounded = differences(argv[1], argv[2])
    for line in found:
        print("DIFFERENT  " + line)
    if found:
        print("%d difference(s) between %s and %s." % (len(found), argv[1], argv[2]))
        return 1
    if rounded:
        print("Same tables: %d value(s) differ after the ninth significant digit, the rest is identical." % rounded)
    else:
        print("Same tables: every value is identical (dates, commit and library versions aside).")
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv))
